public class MainActivity extends Activity {
 private static final String HOME="home",SWIFT="swift",CODE="code",BANKS="banks",STATES="states",DISTRICTS="districts",BRANCHES="branches",DETAIL="detail",SAVED="saved";
 private final ExecutorService worker=Executors.newSingleThreadExecutor(),syncWorker=Executors.newSingleThreadExecutor();private BankImages logos;
 private BranchRepository.Dataset data;private DirectoryIndex index;
 private LinearLayout root,body;private TextView status,caption,lastUpdated;private EditText searchBox;private ListView list;private RowAdapter adapter;
 private String screen=HOME,origin=CODE,bankKey="",stateName="",districtName="",selectedIfsc="",query="",filter="",syncMessage="Loading saved data…";
 private boolean micr=false,refreshing=false,submitted=false;private int generation=0,searchRequest=0;
 private final Set<String> favorites=new LinkedHashSet<>();
 private final int blue=Color.rgb(33,93,224),navy=Color.rgb(19,34,66),muted=Color.rgb(103,118,142),green=Color.rgb(12,118,94),background=Color.rgb(245,247,252);
 @Override public void onCreate(Bundle saved){super.onCreate(saved);logos=new BankImages(this);try{JSONArray a=new JSONArray(getPreferences(0).getString("favorites","[]"));for(int i=0;i<a.length();i++)favorites.add(a.getString(i));}catch(Exception ignored){}
  if(saved!=null){screen=saved.getString("screen",HOME);origin=saved.getString("origin",CODE);bankKey=saved.getString("bank","");stateName=saved.getString("state","");districtName=saved.getString("district","");selectedIfsc=saved.getString("ifsc","");query=saved.getString("query","");filter=saved.getString("filter","");micr=saved.getBoolean("micr");submitted=saved.getBoolean("submitted");}
  render();load();if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->back());
 }
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private TextView text(String label,int size,int color){TextView t=new TextView(this);t.setText(label);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(4),0,dp(4));return t;}
 private TextView bold(String label,int size,int color){TextView t=text(label,size,color);t.setTypeface(null,Typeface.BOLD);return t;}
 private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private android.graphics.drawable.Drawable touch(int color,int radius){return new RippleDrawable(android.content.res.ColorStateList.valueOf(0x18215DE0),shape(color,radius),shape(Color.WHITE,radius));}
 private LinearLayout vertical(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);return v;}
 private LinearLayout card(int color){LinearLayout v=vertical();v.setPadding(dp(18),dp(16),dp(18),dp(16));v.setBackground(touch(color,20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(8),0,dp(8));v.setLayoutParams(p);return v;}
 private Button action(String name,int color,Runnable run){Button b=new Button(this);b.setText(name);b.setAllCaps(false);b.setTextSize(15);b.setTypeface(null,Typeface.BOLD);b.setTextColor(Color.WHITE);b.setBackground(touch(color,13));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(50));p.setMargins(0,dp(12),0,dp(2));b.setLayoutParams(p);b.setOnClickListener(v->run.run());return b;}
 private TextView link(String label,Runnable run){TextView v=bold(label,14,blue);v.setPadding(dp(8),dp(14),dp(8),dp(14));v.setOnClickListener(x->run.run());v.setFocusable(true);return v;}
 private ImageView icon(int res,int tint,int size){ImageView v=new ImageView(this);v.setImageResource(res);v.setColorFilter(tint);v.setScaleType(ImageView.ScaleType.FIT_CENTER);v.setLayoutParams(new LinearLayout.LayoutParams(dp(size),dp(size)));return v;}
 private void navigate(String next){hideKeyboard();filter="";screen=next;render();}
 private void hideKeyboard(){if(searchBox!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(searchBox.getWindowToken(),0);}
 private void render(){generation++;searchRequest++;searchBox=null;list=null;adapter=null;caption=null;
  root=vertical();root.setBackgroundColor(background);setContentView(root);
  if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets n=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(n.left,n.top,n.right,n.bottom);return i;});}
  else root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();
  LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(12),dp(6),dp(14),dp(6));
  ImageView app=new ImageView(this);app.setImageResource(R.drawable.app_logo);app.setScaleType(ImageView.ScaleType.FIT_CENTER);app.setContentDescription("Go to home page");app.setPadding(dp(4),dp(4),dp(4),dp(4));app.setBackground(touch(Color.WHITE,12));app.setFocusable(true);app.setOnClickListener(v->navigate(HOME));top.addView(app,new LinearLayout.LayoutParams(dp(48),dp(48)));
  TextView title=bold("IFSC and MICR Code",17,navy);title.setPadding(dp(10),0,dp(6),0);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView refresh=link("↻ Refresh",()->refresh());refresh.setContentDescription("Refresh GitHub data");top.addView(refresh);root.addView(top);
  if(!screen.equals(HOME))root.addView(link("‹ Back",()->back()));
  status=text(statusText(),12,muted);status.setPadding(dp(22),dp(2),dp(22),dp(8));root.addView(status);lastUpdated=text(modifiedLabel(),12,muted);lastUpdated.setPadding(dp(22),0,dp(22),dp(8));root.addView(lastUpdated);
  body=vertical();body.setPadding(dp(20),0,dp(20),dp(8));root.addView(body,new LinearLayout.LayoutParams(-1,0,1));
  if(screen.equals(HOME))home();else if(screen.equals(CODE))codeScreen();else if(screen.equals(SWIFT))swiftScreen();else if(screen.equals(DETAIL))detailScreen();else browseScreen();
 }
 private String statusText(){return syncMessage+(data==null?"":data.meta.optBoolean("sample_data",true)?" · Unverified examples":" · Available offline");}
 private void updateStatus(){if(status!=null)status.setText(statusText());if(lastUpdated!=null)lastUpdated.setText(modifiedLabel());}
 private LinearLayout scroller(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);LinearLayout c=vertical();scroll.addView(c);body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));return c;}
 private void home(){LinearLayout c=scroller();
  LinearLayout hero=card(blue);GradientDrawable gradient=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{blue,Color.rgb(44,64,166)});gradient.setCornerRadius(dp(22));hero.setBackground(gradient);hero.addView(text("YOUR BANK, ONE SEARCH AWAY",11,0xFFD9E5FF));hero.addView(bold("Find the right\nbank branch.",29,Color.WHITE));hero.addView(text("Search a code or explore banks by location.",14,0xFFE2EAFF));c.addView(hero);
  LinearLayout first=card(Color.WHITE);first.addView(icon(R.drawable.ic_search,blue,32));first.addView(bold("Search by IFSC code",21,navy));first.addView(text("Have a code? Find branch details instantly.\nMICR search is included too.",14,muted));first.addView(action("Search IFSC / MICR  →",blue,()->{query="";submitted=false;navigate(CODE);}));c.addView(first);
  LinearLayout second=card(Color.WHITE);second.addView(icon(R.drawable.ic_bank,green,32));second.addView(bold("Search by bank",21,navy));second.addView(text("Choose your bank, state and district to find a branch.",14,muted));second.addView(action("Browse banks  →",green,()->navigate(BANKS)));c.addView(second);
  LinearLayout third=card(Color.WHITE);third.addView(icon(R.drawable.ic_bank,0xFF7653B5,32));third.addView(bold("Search by SWIFT code",21,navy));third.addView(text("Look up available branch SWIFT / BIC codes for international transfers.",14,muted));third.addView(action("Search SWIFT / BIC  →",0xFF7653B5,()->{query="";submitted=false;navigate(SWIFT);}));c.addView(third);
  LinearLayout utilities=new LinearLayout(this);utilities.setGravity(Gravity.CENTER);utilities.addView(link("Saved branches ("+favorites.size()+")",()->navigate(SAVED)));c.addView(utilities);
  if(data!=null&&(data.meta.optInt("skipped_records")>0||data.meta.optInt("missing_locations")>0))c.addView(text("Some source records have missing bank or location links. Unmatched locations appear as Not provided.",12,muted));
  if(data!=null)c.addView(text(data.branchCount+" branches  ·  "+index.banks.size()+" banks in this directory",13,muted));
  if(data!=null&&data.meta.optBoolean("sample_data",true))c.addView(text("Current records are unverified examples. Confirm details with your bank before making a payment.",12,0xFF9B5C16));
  c.addView(text("BANK PIE · IFSC & MICR directory",12,muted));
 }
 private void heading(String title,String subtitle){body.addView(bold(title,24,navy));body.addView(text(subtitle,13,muted));}
 private EditText input(String hint,boolean code){EditText v=new EditText(this);v.setSingleLine(true);v.setTextSize(16);v.setHint(hint);v.setContentDescription(hint);v.setPadding(dp(15),dp(12),dp(15),dp(12));v.setBackground(shape(Color.WHITE,13));v.setInputType(android.text.InputType.TYPE_CLASS_TEXT);v.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,dp(12),0,dp(8));v.setLayoutParams(p);return v;}
 private void prepareList(){caption=text("",12,muted);body.addView(caption);list=new ListView(this);list.setDivider(null);list.setCacheColorHint(Color.TRANSPARENT);list.setClipToPadding(false);list.setPadding(0,0,0,dp(8));adapter=new RowAdapter();list.setAdapter(adapter);list.setOnItemClickListener((p,v,position,id)->choose(adapter.rows.get(position)));body.addView(list,new LinearLayout.LayoutParams(-1,0,1));}
 private void codeScreen(){heading("Search a branch","Enter IFSC or MICR. Partial codes show up to 8 matches.");RadioGroup mode=new RadioGroup(this);mode.setOrientation(0);RadioButton a=new RadioButton(this),b=new RadioButton(this);a.setText("IFSC code");b.setText("MICR code");a.setId(View.generateViewId());b.setId(View.generateViewId());mode.addView(a);mode.addView(b);mode.check(micr?b.getId():a.getId());body.addView(mode);
  searchBox=input("Enter IFSC code",true);configureCode();searchBox.setText(query);body.addView(searchBox);mode.setOnCheckedChangeListener((g,id)->{micr=id==b.getId();query="";submitted=false;configureCode();searchBox.setText("");searchRequest++;adapter.set(Collections.emptyList());caption.setText("Enter at least 3 characters to search.");});
  searchBox.addTextChangedListener(new Watch(){public void afterTextChanged(Editable e){query=e.toString();submitted=false;searchRequest++;}});
  body.addView(action("Find branch",blue,()->runCodeSearch()));searchBox.setOnEditorActionListener((v,id,event)->{if(id==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH){runCodeSearch();return true;}return false;});prepareList();caption.setText("Enter at least 3 characters to search.");if(submitted)runCodeSearch();
 }
 private void swiftScreen(){
  heading("Find a SWIFT / BIC code","Search branch codes supplied in the directory.");
  searchBox=input("Enter SWIFT / BIC code",true);searchBox.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);searchBox.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.AllCaps(),new android.text.InputFilter.LengthFilter(11)});searchBox.setText(query);body.addView(searchBox);
  searchBox.addTextChangedListener(new Watch(){public void afterTextChanged(Editable e){query=e.toString();submitted=false;searchRequest++;if(adapter!=null)adapter.set(Collections.emptyList());}});
  body.addView(action("Find SWIFT code",0xFF7653B5,()->runSwiftSearch()));searchBox.setOnEditorActionListener((v,id,event)->{if(id==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH){runSwiftSearch();return true;}return false;});prepareList();caption.setText("Enter at least 3 characters. Results require SWIFT data from the directory.");if(submitted)runSwiftSearch();
 }
 private void runSwiftSearch(){
  query=Search.normalize(searchBox.getText().toString());if(!query.matches("[A-Z0-9]{3,11}")){searchBox.setError("Enter 3–11 letters or digits");return;}searchBox.setError(null);submitted=true;hideKeyboard();if(data==null){caption.setText("Download the directory using Refresh, then search again.");return;}
  final int g=generation,t=++searchRequest;final String q=query;final BranchRepository.Dataset snapshot=data;caption.setText("Searching…");
  worker.execute(()->{try{boolean available=snapshot.hasSwift();List<Row> rows=new ArrayList<>();for(JSONObject b:snapshot.searchSwift(q))rows.add(new Row("branch",BranchRepository.clean(b,"ifsc"),BranchRepository.clean(b,"swift"),BranchRepository.clean(b,"bank_name")+" · "+BranchRepository.clean(b,"branch_name"),BranchRepository.clean(b,"bank_image"),b));runOnUiThread(()->{if(isDestroyed()||g!=generation||t!=searchRequest)return;adapter.set(rows);caption.setText(!available?"SWIFT data not available in the current directory. Please contact your bank for its SWIFT / BIC code.":rows.isEmpty()?"No matching SWIFT code found.":rows.size()+" matching branches · tap for details");});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()&&g==generation&&t==searchRequest)caption.setText("Could not search SWIFT codes. Refresh and try again.");});}});
 }
 private void configureCode(){searchBox.setHint(micr?"Enter MICR · e.g. 400002001":"Enter IFSC · e.g. SBIN0001234");searchBox.setInputType(micr?android.text.InputType.TYPE_CLASS_NUMBER:android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);searchBox.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(micr?9:11)});}
 private void runCodeSearch(){query=Search.normalize(searchBox.getText().toString());if(!Search.validQuery(query,micr)){searchBox.setError(micr?"Enter 3–9 digits":"Enter 3–11 letters or digits");return;}searchBox.setError(null);submitted=true;hideKeyboard();if(data==null){caption.setText(refreshing?"Downloading branch data…":"Connect to internet and tap Refresh to download the directory.");return;}caption.setText("Searching…");final int g=generation,t=++searchRequest;final boolean useMicr=micr;final String q=query;final BranchRepository.Dataset snapshot=data;
  worker.execute(()->{List<JSONObject> matches;try{matches=snapshot.search(q,useMicr);}catch(Exception e){runOnUiThread(()->{if(g==generation&&t==searchRequest)caption.setText("Search failed. Refresh the directory and try again.");});return;}List<Row> rows=new ArrayList<>();for(JSONObject b:matches)rows.add(branchRow(b));runOnUiThread(()->{if(isDestroyed()||g!=generation||t!=searchRequest)return;adapter.set(rows);caption.setText(rows.isEmpty()?"No matches. Try a shorter code or refresh the directory.":rows.size()+" matching branches · tap for details");});});
 }
 private void browseScreen(){String title=screen.equals(BANKS)?"Choose your bank":screen.equals(STATES)?"Choose a state":screen.equals(DISTRICTS)?"Choose a district":screen.equals(SAVED)?"Saved branches":"Choose a branch";
  String subtitle=screen.equals(BANKS)?"Browse banks and their available branches":screen.equals(SAVED)?"Your saved branches, ready to find again":bankName()+(screen.equals(STATES)?"":"  ›  "+stateName)+(screen.equals(BRANCHES)?"  ›  "+districtName:"");heading(title,subtitle);
  searchBox=input(screen.equals(BANKS)?"Search bank name":screen.equals(STATES)?"Search state":screen.equals(DISTRICTS)?"Search district":"Search branch or IFSC",false);searchBox.setText(filter);body.addView(searchBox);prepareList();searchBox.addTextChangedListener(new Watch(){public void afterTextChanged(Editable e){filter=e.toString();fillBrowse();}});fillBrowse();
 }
 private String bankName(){DirectoryIndex.Bank b=index==null?null:index.banks.get(bankKey);return b==null?"Bank":b.name;}
 private void fillBrowse(){if(adapter==null||screen.equals(CODE)||screen.equals(SWIFT)||screen.equals(DETAIL)||screen.equals(HOME))return;if(index==null){adapter.set(Collections.emptyList());caption.setText(refreshing?"Downloading directory…":"No saved directory. Connect to internet and tap Refresh.");return;}
  final int g=generation,t=++searchRequest;final String current=screen,bk=bankKey,st=stateName,di=districtName,q=filter.trim().toLowerCase(Locale.ROOT);final DirectoryIndex snapshot=index;final Set<String> saved=new HashSet<>(favorites);
  worker.execute(()->{List<Row> rows=new ArrayList<>();DirectoryIndex.Bank b=snapshot.banks.get(bk);
   if(current.equals(BANKS)){for(DirectoryIndex.Bank item:snapshot.orderedBanks()){if(item.name.toLowerCase(Locale.ROOT).contains(q))rows.add(new Row("bank",item.key,item.name,item.branches.size()+" branches available",item.image,null));}}
   else if(current.equals(SAVED)){for(String code:saved){JSONObject branch=snapshot.byIfsc.get(code);if(branch!=null&&matches(branch,q))rows.add(branchRow(branch));}rows.sort(Comparator.comparing(r->r.title,String.CASE_INSENSITIVE_ORDER));}
   else if(b!=null&&current.equals(STATES)){for(Map.Entry<String,SortedMap<String,List<JSONObject>>> e:b.locations.entrySet()){int n=0;for(List<JSONObject> a:e.getValue().values())n+=a.size();if(e.getKey().toLowerCase(Locale.ROOT).contains(q))rows.add(new Row("state",e.getKey(),e.getKey(),e.getValue().size()+" districts · "+n+" branches","",null));}}
   else if(b!=null&&current.equals(DISTRICTS)){SortedMap<String,List<JSONObject>> districts=b.locations.get(st);if(districts!=null)for(Map.Entry<String,List<JSONObject>> e:districts.entrySet())if(e.getKey().toLowerCase(Locale.ROOT).contains(q))rows.add(new Row("district",e.getKey(),e.getKey(),e.getValue().size()+" branches","",null));}
   else if(current.equals(BRANCHES))try{for(JSONObject branch:snapshot.branches(bk,st,di))if(matches(branch,q))rows.add(branchRow(branch));}catch(Exception e){runOnUiThread(()->{if(g==generation&&t==searchRequest)caption.setText("Could not read branches. Refresh the directory.");});return;}
   runOnUiThread(()->{if(isDestroyed()||g!=generation||t!=searchRequest)return;adapter.set(rows);String empty=current.equals(SAVED)?"No saved branches available. Open a branch and tap Save.":"No entries available for this selection.";caption.setText(rows.isEmpty()?empty:rows.size()+" "+(current.equals(BANKS)?"banks":current.equals(STATES)?"states":current.equals(DISTRICTS)?"districts":"branches")+" · tap to continue");});
  });
 }
 private static boolean matches(JSONObject b,String q){return (BranchRepository.clean(b,"branch_name")+" "+BranchRepository.clean(b,"ifsc")+" "+BranchRepository.clean(b,"city")).toLowerCase(Locale.ROOT).contains(q);}
 private Row branchRow(JSONObject b){return new Row("branch",BranchRepository.clean(b,"ifsc"),BranchRepository.clean(b,"branch_name"),BranchRepository.clean(b,"ifsc")+"\n"+BranchRepository.clean(b,"bank_name")+" · "+DirectoryIndex.location(b,"district"),BranchRepository.clean(b,"bank_image"),b);}
 private void choose(Row row){if(row.kind.equals("bank")){bankKey=row.key;navigate(STATES);}else if(row.kind.equals("state")){stateName=row.key;navigate(DISTRICTS);}else if(row.kind.equals("district")){districtName=row.key;navigate(BRANCHES);}else {origin=screen;selectedIfsc=row.key;hideKeyboard();screen=DETAIL;render();}}
 private void detailScreen(){LinearLayout c=scroller();JSONObject b=index==null?null:index.byIfsc.get(selectedIfsc);if(b==null){c.addView(bold("Branch unavailable",24,navy));c.addView(text(data==null?"Loading the branch directory…":"This branch is not present in the current directory. Return to search or refresh.",15,muted));return;}
  LinearLayout hero=card(Color.WHITE);addLogoTitle(hero,BranchRepository.clean(b,"bank_name"),BranchRepository.clean(b,"bank_image"));hero.addView(bold(BranchRepository.clean(b,"branch_name"),24,navy));hero.addView(text(DirectoryIndex.location(b,"district")+" · "+DirectoryIndex.location(b,"state"),13,muted));c.addView(hero);
  if(data.meta.optBoolean("sample_data",true))c.addView(text("UNVERIFIED EXAMPLE · Confirm with your bank before payment.",12,0xFFA76015));
  LinearLayout code=card(0xFFEAF0FF);code.addView(text("IFSC CODE",11,blue));TextView codeValue=bold(selectedIfsc,27,navy);codeValue.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);codeValue.setTextIsSelectable(true);code.addView(codeValue);code.addView(action("Copy IFSC",blue,()->copy("IFSC",selectedIfsc)));c.addView(code);
  LinearLayout actions=new LinearLayout(this);actions.addView(link(favorites.contains(selectedIfsc)?"★ Saved":"☆ Save branch",()->{if(favorites.contains(selectedIfsc))favorites.remove(selectedIfsc);else favorites.add(selectedIfsc);getPreferences(0).edit().putString("favorites",new JSONArray(favorites).toString()).apply();render();}));actions.addView(link("Share details",()->share(b)));c.addView(actions);
  LinearLayout info=card(Color.WHITE);info.addView(bold("Bank & branch",18,navy));for(String k:new String[]{"bank_name","branch_name","micr","swift","branch_code","branch_status"})field(info,k,value(b,k));String swift=BranchRepository.clean(b,"swift");if(!swift.isEmpty())info.addView(link("Copy SWIFT / BIC",()->copy("SWIFT / BIC",swift)));c.addView(info);
  LinearLayout location=card(Color.WHITE);location.addView(bold("Location & contact",18,navy));for(String k:new String[]{"address","district","state","contact"})field(location,k,value(b,k));String addr=BranchRepository.clean(b,"address");if(!addr.isEmpty())location.addView(link("View address on map  ↗",()->open("geo:0,0?q="+android.net.Uri.encode(addr))));String phone=BranchRepository.clean(b,"contact");if(phone.matches("[+0-9() .-]{6,25}"))location.addView(link("Call branch  ↗",()->open("tel:"+phone.replaceAll("[^+0-9]",""))));c.addView(location);
  LinearLayout bankContact=card(Color.WHITE);bankContact.addView(bold("Bank contact",18,navy));for(String k:new String[]{"bank_contact","bank_email","bank_website"})field(bankContact,k,value(b,k));String website=BranchRepository.clean(b,"bank_website"),email=BranchRepository.clean(b,"bank_email");if(website.matches("https?://.+"))bankContact.addView(link("Visit bank website  ↗",()->open(website)));if(email.contains("@")&&!email.contains(" "))bankContact.addView(link("Email bank  ↗",()->open("mailto:"+android.net.Uri.encode(email))));c.addView(bankContact);
  LinearLayout services=card(Color.WHITE);services.addView(bold("Transfer services",18,navy));for(String k:new String[]{"neft","rtgs","imps","upi"})field(services,k,value(b,k));c.addView(services);
  Set<String> known=new HashSet<>(Arrays.asList("bank_name","bank_image","city","bank","branch","ifsc_code","id","bank_id","state_id","district_id","phone","branch_status","bank_contact","bank_email","bank_website","branch_name","ifsc","micr","swift","branch_code","address","district","state","contact","is_active","neft","rtgs","imps","upi"));Iterator<String> keys=b.keys();LinearLayout extra=card(Color.WHITE);extra.addView(bold("More branch information",18,navy));boolean hasExtra=false;while(keys.hasNext()){String k=keys.next();if(!known.contains(k)){field(extra,k,value(b,k));hasExtra=true;}}if(hasExtra)c.addView(extra);
  c.addView(text("Directory source: "+BranchRepository.clean(data.meta,"source"),11,muted));c.addView(text(modifiedLabel(),11,muted));JSONObject modified=data.meta.optJSONObject("file_modified");if(modified!=null)for(String file:new String[]{"banks.json","state.json","district.json","branch.json"})c.addView(text(file+": "+(BranchRepository.clean(modified,file).isEmpty()?"Date unavailable":BranchRepository.clean(modified,file)),11,muted));
 }
 private String value(JSONObject b,String k){Object v=b.opt(k);if(v==null||v==JSONObject.NULL||String.valueOf(v).trim().isEmpty())return "Not provided";if(v instanceof Boolean)return (Boolean)v?(k.equals("is_active")?"Active":"Supported"):(k.equals("is_active")?"Inactive":"Not supported");return String.valueOf(v);}
 private void field(LinearLayout card,String name,String value){TextView label=text(name.replace('_',' ').toUpperCase(Locale.ROOT),11,muted);label.setPadding(0,dp(13),0,0);card.addView(label);TextView val=text(value,15,navy);val.setTextIsSelectable(true);card.addView(val);}
 private void addLogoTitle(LinearLayout parent,String title,String image){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);ImageView v=new ImageView(this);v.setScaleType(ImageView.ScaleType.FIT_CENTER);v.setContentDescription(title);v.setBackground(shape(0xFFF2F5FC,12));v.setPadding(dp(6),dp(6),dp(6),dp(6));row.addView(v,new LinearLayout.LayoutParams(dp(52),dp(52)));logos.load(v,image);TextView name=bold(title,16,navy);name.setPadding(dp(12),0,0,0);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));parent.addView(row);}
 private void copy(String label,String value){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText(label,value));Toast.makeText(this,label+" copied",Toast.LENGTH_SHORT).show();}
 private void share(JSONObject b){StringBuilder s=new StringBuilder("IFSC and MICR Code\n");if(data.meta.optBoolean("sample_data",true))s.append("Unverified example — confirm with your bank\n");Iterator<String> it=b.keys();while(it.hasNext()){String k=it.next();if(!Arrays.asList("bank_image","city","id","bank_id","state_id","district_id","ifsc_code","bank","branch","phone").contains(k))s.append(k.replace('_',' ')).append(": ").append(value(b,k)).append('\n');}Intent share=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,s.toString());startActivity(Intent.createChooser(share,"Share branch details"));}
 private void open(String uri){try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(uri)));}catch(ActivityNotFoundException e){Toast.makeText(this,"No compatible app installed",Toast.LENGTH_SHORT).show();}}
 private void back(){if(screen.equals(HOME)){finish();return;}hideKeyboard();if(screen.equals(DETAIL))screen=origin;else if(screen.equals(BRANCHES)){screen=DISTRICTS;filter="";}else if(screen.equals(DISTRICTS)){screen=STATES;filter="";}else if(screen.equals(STATES)){screen=BANKS;filter="";}else screen=HOME;render();}
 @Override public void onBackPressed(){back();}
 @Override protected void onSaveInstanceState(Bundle s){super.onSaveInstanceState(s);s.putString("screen",screen);s.putString("origin",origin);s.putString("bank",bankKey);s.putString("state",stateName);s.putString("district",districtName);s.putString("ifsc",selectedIfsc);s.putString("query",query);s.putString("filter",filter);s.putBoolean("micr",micr);s.putBoolean("submitted",submitted);}
 private String modifiedLabel(){if(data==null)return "Last updated: awaiting first download";String date=BranchRepository.clean(data.meta,"updated_at");if(date.isEmpty())return "Last updated: unavailable from GitHub";try{return "Last updated: "+java.time.format.DateTimeFormatter.ofPattern("dd MMM yyyy, h:mm a",Locale.getDefault()).withZone(java.time.ZoneId.systemDefault()).format(java.time.Instant.parse(date));}catch(Exception e){return "Last updated: "+date;}}
 private void load(){worker.execute(()->{BranchRepository.Dataset local=null;DirectoryIndex built=null;try{local=BranchRepository.load(this);built=new DirectoryIndex(local);}catch(Exception ignored){if(local!=null)local.close();local=null;}
  final BranchRepository.Dataset loaded=local;final DirectoryIndex prepared=built;runOnUiThread(()->{if(isDestroyed()){if(loaded!=null)loaded.close();return;}data=loaded;index=prepared;if(loaded!=null)logos.setRevision(BranchRepository.clean(loaded.meta,"revision"));syncMessage=loaded==null?"First download requires internet":"Saved GitHub data ready";render();refresh();});
 });}
 private void refresh(){if(refreshing)return;refreshing=true;syncMessage="Updating all four files… first download may take a few minutes";updateStatus();final BranchRepository.Dataset previous=data;syncWorker.execute(()->{try{BranchRepository.Dataset fresh=BranchRepository.fetch(this,previous,message->runOnUiThread(()->{if(!isDestroyed()){syncMessage=message;updateStatus();}}));DirectoryIndex built=fresh==previous?index:new DirectoryIndex(fresh);
  runOnUiThread(()->{if(isDestroyed()){if(fresh!=previous)fresh.close();return;}refreshing=false;data=fresh;index=built;syncMessage="GitHub directory ready · "+fresh.branchCount+" branches";logos.setRevision(BranchRepository.clean(fresh.meta,"revision"));if(fresh!=previous&&previous!=null)worker.execute(()->{previous.close();BranchRepository.delete(previous.directory);});if(screen.equals(HOME)||screen.equals(DETAIL))render();else {updateStatus();if(screen.equals(CODE)&&submitted)runCodeSearch();else if(screen.equals(SWIFT)&&submitted)runSwiftSearch();else fillBrowse();}});
  }catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;refreshing=false;syncMessage=data==null?"Download failed: "+e.getMessage():"Update unavailable · using saved data";updateStatus();if(!screen.equals(CODE))fillBrowse();});}});}
 @Override protected void onDestroy(){super.onDestroy();if(!worker.isShutdown())worker.execute(()->{if(data!=null)data.close();});worker.shutdown();syncWorker.shutdownNow();logos.close();}
 private abstract static class Watch implements TextWatcher {public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){}}
 private static final class Row {final String kind,key,title,subtitle,image;final JSONObject branch;Row(String kind,String key,String title,String subtitle,String image,JSONObject branch){this.kind=kind;this.key=key;this.title=title;this.subtitle=subtitle;this.image=image;this.branch=branch;}}
 private final class RowAdapter extends BaseAdapter {
  List<Row> rows=Collections.emptyList();void set(List<Row> items){rows=items;notifyDataSetChanged();}public int getCount(){return rows.size();}public Object getItem(int p){return rows.get(p);}public long getItemId(int p){return p;}
  public View getView(int p,View recycled,ViewGroup parent){Row row=rows.get(p);Holder h;if(recycled==null){LinearLayout outer=vertical();outer.setPadding(0,dp(5),0,dp(5));LinearLayout c=new LinearLayout(MainActivity.this);c.setGravity(Gravity.CENTER_VERTICAL);c.setPadding(dp(14),dp(16),dp(14),dp(16));c.setBackground(touch(Color.WHITE,17));outer.addView(c);ImageView image=new ImageView(MainActivity.this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setPadding(dp(6),dp(6),dp(6),dp(6));image.setBackground(shape(0xFFF1F5FD,12));c.addView(image,new LinearLayout.LayoutParams(dp(46),dp(46)));LinearLayout labels=vertical();labels.setPadding(dp(13),0,dp(8),0);TextView name=bold("",16,navy),sub=text("",12,muted);labels.addView(name);labels.addView(sub);c.addView(labels,new LinearLayout.LayoutParams(0,-2,1));c.addView(text("›",26,blue));h=new Holder(image,name,sub);outer.setTag(h);recycled=outer;}else h=(Holder)recycled.getTag();h.title.setText(row.title);h.subtitle.setText(row.subtitle);h.image.clearColorFilter();if(row.kind.equals("bank")||row.kind.equals("branch"))logos.load(h.image,row.image);else{h.image.setTag("");h.image.setImageResource(R.drawable.ic_location);h.image.setColorFilter(green);}recycled.setContentDescription(row.title+". "+row.subtitle+". Tap to continue");return recycled;
  }
 }
 private static final class Holder {final ImageView image;final TextView title,subtitle;Holder(ImageView image,TextView title,TextView subtitle){this.image=image;this.title=title;this.subtitle=subtitle;}}
}
